import sys

def is_cyclic_shift(s, t):
    return len(s) == len(t) and s in (t + t)

def is_good_message(message, sx):
    k = len(message)
    cyclic_shifts = {message[i:] + message[:i] for i in range(k)}
    return all(shift in sx for shift in cyclic_shifts)

def is_stable(L):
    sx = set()
    current = ""
    for s in L:
        current += s
        sx.add(current)
    return all(is_good_message(m, sx) for m in sx)

def main():
    import sys
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    A = input[1:]
    total = 0
    for start in range(n):
        for end in range(start + 1, n + 1):
            if is_stable(A[start:end]):
                total += 1
    print(total)

main()
